import{ThemeEvents,VariantUpdateEvent}from"@theme/events";import{morph}from"@theme/morph";import{Component}from"@theme/component";class ProductInventory extends Component{connectedCallback(){super.connectedCallback();const t=this.closest(".shopify-section, dialog");t?.addEventListener(ThemeEvents.variantUpdate,this.updateInventory)}disconnectedCallback(){super.disconnectedCallback();const t=this.closest(".shopify-section, dialog");t?.removeEventListener(ThemeEvents.variantUpdate,this.updateInventory)}updateInventory=t=>{if(t.detail.data.newProduct)this.dataset.productId=t.detail.data.newProduct.id;else if(t.target instanceof HTMLElement&&t.target.dataset.productId!==this.dataset.productId)return;const e=t.detail.data.html.querySelector("product-inventory");e&&morph(this,e,{childrenOnly:!0})}}customElements.get("product-inventory")||customElements.define("product-inventory",ProductInventory);